fn function0(value0: i64, value1: i64) -> Vec<Vec<i64>> {let base=vec![value1,value1.checked_add(1).unwrap(),2,0,value1.checked_add(4).unwrap()];let mut output=Vec::with_capacity(usize::try_from(value0).unwrap());for i in 0..value0{let mode=i.checked_add(value1).unwrap()%4;let count=[0_usize,1,4,5][usize::try_from(mode).unwrap()];let selected=base[..count].to_vec();let first=base[1..usize::try_from(mode%3+2).unwrap()].to_vec();let second=base[..usize::try_from(mode%2).unwrap()].to_vec();let empty:Vec<i64>=Vec::new();let scalar0=value1.checked_add(i).unwrap();let scalar1=i.checked_add(1).unwrap();let mut result=selected;result.push(scalar0);result.extend(first);result.push(scalar1);result.extend(empty);result.extend(second);output.push(result);}output}
